-- PERMANENT: ADA Hub Pilot V0.1 - the whole client engagement, driven ONLY through the existing controlled operations (the ones an interface calls):
-- search -> organization / client -> contact -> project -> service + price -> quote -> approval -> acceptance -> contract / project -> invoice -> payments
-- -> document -> communication -> ticket -> asset -> domain -> Client 360 / Project 360 -> search by name, ID and relationship -> history.
-- It also proves the identity rules of the engagement (no duplicate organization, person or client role; stable IDs; immutable commercial values).
begin;
select tests.setup();
select tests.setup_hr();
select tests.add_staff('adm2', 'administration_officer');
insert into tests.ids values ('x:random', gen_random_uuid());
create function tests.j(p_user text, p_sql text) returns jsonb language plpgsql as $$
declare v text := tests.scalar(p_user, p_sql);
begin return case when v like 'ERR:%' then to_jsonb(v) else v::jsonb end; end $$;
create function tests.rid(p_inst text) returns uuid language sql stable as $$ select entity_id from entity_registry where institutional_id = p_inst $$;

-- The catalogue and the bank account (administrative set-up that exists before any engagement) --------------------------------------------------------
select tests.remember('svc:wd', tests.scalar('web_lead', $q$ insert into services (division_id, name, summary, description, category) select id, 'Website Development', 'A business website', 'Design and build', 'web' from divisions where key = 'web' returning id::text $q$));
select tests.remember('price:wd1', tests.scalar('web_lead', format('select price_propose(%L, 5000, ''NAD'', current_date, ''launch price'')::text', tests.id('svc:wd'))));
select tests.scalar('ceo', format('select (price_decide(%L, true)).status::text', tests.id('price:wd1')));
select tests.bank_account('main');
select tests.check('the catalogue the forms read lists the divisions, the service with the price in force today, the bank account and the staff - as the caller may see them',
  tests.scalar('web_lead', $q$ select concat_ws('|', jsonb_array_length(pilot_catalogue() -> 'divisions'), (select s ->> 'name' || '=' || (s -> 'price' ->> 'amount') from jsonb_array_elements(pilot_catalogue() -> 'services') s limit 1), jsonb_array_length(pilot_catalogue() -> 'bank_accounts')) $q$), '9|Website Development=5000.00|0');
select tests.check('the bank accounts are visible to finance (who record payments), not to the sales team', tests.scalar('fin', $q$ select jsonb_array_length(pilot_catalogue() -> 'bank_accounts')::text $q$), '1');

-- 1. Search first -----------------------------------------------------------------------------------------------------------------------------------------
select tests.check('searching ADA Hub for Zeta finds nothing yet, and the client look-up finds no candidate', tests.scalar('web_lead', $q$ select (search('zeta')->>'total') || client_lookup('Zeta Test Company')::text $q$), '0[]');
-- 2. Organization + client role ------------------------------------------------------------------------------------------------------------------------
select tests.remember('zeta', tests.scalar('web_lead', format($q$ select (client_create('Zeta Test Company', %L, 'company', 'ZT-2026/001', 'info@zeta.example', '+264 61 555 0101') ->> 'id') $q$, tests.id('div:web'))));
select tests.check('the client is created through the controlled operation and the ONE organization behind it is registered (permanent IDs for both)',
  (select concat_ws('|', (c.ada_id ~ '^ADA-CLI-')::text, (cr.institutional_id ~ '^[0-9A-HJKMNP-TV-Z]{9}$')::text, (orr.institutional_id ~ '^[0-9A-HJKMNP-TV-Z]{9}$')::text, orr.entity_type, (c.organization_id = orr.entity_id)::text)
     from clients c join entity_registry cr on cr.table_name = 'clients' and cr.entity_id = c.id join entity_registry orr on orr.table_name = 'organizations' and orr.entity_id = c.organization_id where c.id = tests.id('zeta')), 'true|true|true|external_organization|true');
create temp table zeta as select (select institutional_id from entity_registry where table_name = 'clients' and entity_id = tests.id('zeta')) as client_inst,
  (select ada_id from clients where id = tests.id('zeta')) as client_ada, (select organization_id from clients where id = tests.id('zeta')) as org_id,
  (select institutional_id from entity_registry where table_name = 'organizations' and entity_id = (select organization_id from clients where id = tests.id('zeta'))) as org_inst;
select tests.check('a user working in ANOTHER division cannot create a second "Zeta Test Company": the same call, with another spelling, reports the existing client - one organization, one client',
  tests.scalar('tech_lead', format($q$ select (client_create('Zeta Test Company', %L)->>'status') $q$, tests.id('div:tech'))) || '|' || tests.scalar('tech_lead', format($q$ select (client_create('ZETA TEST COMPANY (Pty) Ltd', %L)->>'status') $q$, tests.id('div:tech'))) || '|' ||
  (select count(*)::text from clients where name_key like 'zeta%') || (select count(*)::text from organizations where name_key like 'zeta%'), 'exists|exists|11');
select tests.check('look-up before creating reports the existing client to the other division too', tests.scalar('tech_lead', $q$ select (client_lookup('Zeta Test Company') -> 0 ->> 'match') $q$), 'exact_name');
select tests.check('another division joins the same client through the controlled claim - still one client, one organization, the IDs unchanged',
  tests.try('tech_lead', format($q$ select claim_client_for_division(%L, %L) $q$, tests.id('zeta'), tests.id('div:tech'))) || (select count(*)::text from clients where name_key like 'zeta%') || (select (client_inst = (select institutional_id from entity_registry where table_name = 'clients' and entity_id = tests.id('zeta')))::text from zeta), 'ok1true');
select tests.check('a different legal entity with a similar name and a DIFFERENT registration number is not merged and not silently duplicated: a distinguishing name is required',
  tests.scalar('web_lead', format($q$ select (client_create('Zeta Test Company', %L, 'company', 'XX-999') ->> 'status') $q$, tests.id('div:web'))), 'name_conflict');
select tests.check('the organization 360 shows one identity with the client role', tests.scalar('web_lead', format($q$ select (organization_360(%L) -> 'organization' ->> 'name') $q$, (select org_id from zeta))), 'Zeta Test Company');

-- 3. Contact (the authoritative person) ----------------------------------------------------------------------------------------------------------------------
select tests.remember('zed', tests.scalar('web_lead', format($q$ select add_client_contact(%L, 'Zed Zeta', 'zed@zeta.example', '+264 81 555 0102', 'Managing Director', true, true)::text $q$, tests.id('zeta'))));
select tests.check('adding the same e-mail again reuses the same contact', (tests.scalar('web_lead', format($q$ select add_client_contact(%L, 'Zed Zeta', 'ZED@zeta.example', null, 'Director', false, false)::text $q$, tests.id('zeta'))) = tests.id('zed')::text)::text, 'true');
select tests.check('...one person and one contact exist', (select count(*)::text from people where lower(email) = 'zed@zeta.example') || (select count(*)::text from client_contacts where client_id = tests.id('zeta')), '11');
select tests.check('the contact is searchable and the person record is the authority (the contact row carries no name or e-mail of its own)', (select coalesce(string_agg(column_name, ','), 'none') from information_schema.columns where table_name = 'client_contacts' and column_name in ('full_name', 'name', 'email', 'phone')), 'none');

-- 4. Project: the central container --------------------------------------------------------------------------------------------------------------------------
select tests.remember('prj', tests.scalar('web_lead', format($q$ select (project_create(%L, %L, 'Zeta Website', 'Corporate website for Zeta', 'website', current_date, current_date + 60) ->> 'id') $q$, tests.id('zeta'), tests.id('div:web'))));
select tests.check('the project is created through the controlled operation: permanent ID, client reference, lead division - and nothing is copied from the client', (select concat_ws('|', (p.ada_id ~ '^ADA-PRJ-')::text, (r.institutional_id ~ '^[0-9A-HJKMNP-TV-Z]{9}$')::text, (p.client_id = tests.id('zeta'))::text, (p.lead_division_id = tests.id('div:web'))::text, p.status::text)
  from projects p join entity_registry r on r.table_name = 'projects' and r.entity_id = p.id where p.id = tests.id('prj')), 'true|true|true|true|proposed');
select tests.check('creating it again (a double submit, or another session) answers with the same project: no duplicate', tests.scalar('web_lead', format($q$ select (project_create(%L, %L, 'ZETA WEBSITE') ->> 'status') || (select count(*) from projects where client_id = %L)::text $q$, tests.id('zeta'), tests.id('div:web'), tests.id('zeta'))), 'exists1');
select tests.check('creating a project needs projects.create in that division, a sensible name, and a client the caller can see', tests.scalar('web_staff', format($q$ select project_create(%L, %L, 'Staff project')::text $q$, tests.id('zeta'), tests.id('div:web'))) || tests.scalar('tech_staff', format($q$ select project_create(%L, %L, 'Tech project')::text $q$, tests.id('zeta'), tests.id('div:tech'))) ||
  tests.scalar('web_lead', format($q$ select project_create(%L, %L, 'x')::text $q$, tests.id('zeta'), tests.id('div:web'))) || tests.scalar('web_lead', format($q$ select project_create(%L, %L, 'No such client')::text $q$, tests.id('x:random'), tests.id('div:web'))), 'ERR:42501ERR:42501ERR:22023ERR:P0002');
select tests.check('participating divisions (management decides which other divisions join: the division lead alone cannot), staff, the shared contact and a task are attached by reference through controlled operations (idempotent)',
  tests.try('web_lead', format($q$ select project_add_division(%L, %L) $q$, tests.id('prj'), tests.id('div:tech'))) || tests.try('adm2', format($q$ select project_add_division(%L, %L) $q$, tests.id('prj'), tests.id('div:tech'))) || tests.try('adm2', format($q$ select project_add_division(%L, %L) $q$, tests.id('prj'), tests.id('div:tech'))) ||
  tests.try('web_lead', format($q$ select project_add_member(%L, %L, 'project manager') $q$, tests.id('prj'), tests.id('staff:web_lead'))) || tests.try('web_lead', format($q$ select project_add_member(%L, %L, 'developer') $q$, tests.id('prj'), tests.id('staff:web_staff'))) ||
  tests.try('web_lead', format($q$ select project_add_contact(%L, %L, 'decision maker') $q$, tests.id('prj'), tests.id('zed'))) || tests.scalar('web_lead', format($q$ select (task_create(%L, 'Collect brand assets', null, %L, current_date + 7) is not null)::text $q$, tests.id('prj'), tests.id('staff:web_staff'))), 'ERR:42501okokokokoktrue');
select tests.check('...and they are references: the project tables carry no names, e-mails or phone numbers of divisions, staff or contacts', (select count(*)::text from information_schema.columns where table_name in ('project_divisions', 'project_members', 'project_contacts') and column_name ~* 'name|email|phone'), '0');
select tests.remember('c2', tests.mkclient_id('web_lead', 'Other Client Ltd', 'web'));
select tests.remember('olive', tests.scalar('web_lead', format($q$ select add_client_contact(%L, 'Olive Other', 'olive@other.example', null, 'Owner', true, false)::text $q$, tests.id('c2'))));
select tests.check('a contact of ANOTHER client cannot be attached to the project', tests.try('web_lead', format($q$ select project_add_contact(%L, %L) $q$, tests.id('prj'), tests.id('olive'))), 'ERR:23514');

-- 5. Service + price, quote, approval, acceptance -------------------------------------------------------------------------------------------------------------
select tests.remember('quote', tests.scalar('web_lead', format($q$ select quote_create(%L, %L, 'Zeta website quote', %L, %L, current_date + 30, 'Quote for the Zeta corporate website', 'Net 30')::text $q$, tests.id('zeta'), tests.id('div:web'), tests.id('zed'), tests.id('prj'))));
select tests.remember('qline', tests.scalar('web_lead', format($q$ select quote_add_line(%L, %L)::text $q$, tests.id('quote'), tests.id('svc:wd'))));
select tests.check('the quote line snapshots the price IN FORCE from the catalogue (N$5,000), records which price version it came from, and nothing was typed in',
  (select concat_ws('|', l.unit_price::text, (l.price_id = tests.id('price:wd1'))::text, (l.price_override_reason is null)::text, (select total::text from quotes where id = tests.id('quote'))) from quote_lines l where l.id = tests.id('qline')), '5000.00|true|true|5000.00');
select tests.check('a price different from the catalogue needs a reason (no silent override)', tests.scalar('web_lead', format($q$ select quote_add_line(%L, %L, 1, 4000)::text $q$, tests.id('quote'), tests.id('svc:wd'))), 'ERR:23514');
select tests.check('submit for approval; the preparer cannot approve their own quote, a person without the right cannot either; the approver can',
  tests.scalar('web_lead', format($q$ select quote_transition(%L, 'pending_approval')::text $q$, tests.id('quote'))) || '|' || tests.scalar('web_lead', format($q$ select quote_transition(%L, 'approved')::text $q$, tests.id('quote'))) || '|' ||
  tests.scalar('web_staff', format($q$ select quote_transition(%L, 'approved')::text $q$, tests.id('quote'))) || '|' || tests.scalar('ceo', format($q$ select quote_transition(%L, 'approved')::text $q$, tests.id('quote'))), 'pending_approval|ERR:42501|ERR:42501|approved');
select tests.check('the approval is on record: decided by a different person, not a self-approval', (select concat_ws('|', r.status::text, (select count(*)::text from approval_decisions d where d.request_id = r.id and not d.is_self)) from approval_requests r where r.entity_table = 'quotes' and r.entity_id = tests.id('quote')), 'approved|1');
select tests.scalar('web_lead', format($q$ select quote_transition(%L, 'sent')::text $q$, tests.id('quote')));
select tests.check('a quote that has been sent can no longer be edited (lines are frozen)', tests.scalar('web_lead', format($q$ select quote_add_line(%L, %L)::text $q$, tests.id('quote'), tests.id('svc:wd'))), 'ERR:42501');
select tests.check('the client accepts: the quote is accepted and the acceptance is kept', tests.scalar('web_lead', format($q$ select quote_transition(%L, 'accepted', 'Signed by Zed Zeta')::text $q$, tests.id('quote'))), 'accepted');

-- price history: the catalogue moves on, the accepted quote does not
select tests.remember('price:wd2', tests.scalar('web_lead', format($q$ select price_propose(%L, 6000, 'NAD', current_date + 1, 'annual review')::text $q$, tests.id('svc:wd'))));
select tests.check('a new price needs approval from someone other than the proposer', tests.scalar('web_lead', format($q$ select (price_decide(%L, true)).status::text $q$, tests.id('price:wd2'))) || '|' || tests.scalar('ceo', format($q$ select (price_decide(%L, true)).status::text $q$, tests.id('price:wd2'))), 'ERR:42501|approved');
select tests.check('the price in force today is still N$5,000; tomorrow N$6,000; the history keeps both versions', (select (price_on(tests.id('svc:wd'), current_date)).amount::text || '|' || (price_on(tests.id('svc:wd'), current_date + 1)).amount::text || '|' || (select count(*)::text from service_prices where service_id = tests.id('svc:wd') and status = 'approved')), '5000.00|6000.00|2');
select tests.check('the accepted quote still says N$5,000 (price version 1) - a later catalogue change never rewrites it', (select l.unit_price::text || '|' || (l.price_id = tests.id('price:wd1'))::text from quote_lines l where l.id = tests.id('qline')), '5000.00|true');
select tests.check('...and neither the stored price version nor the quote line can be edited, even by the database owner', tests.try_owner(format($q$ update service_prices set amount = 1 where id = %L $q$, tests.id('price:wd1'))) || tests.try_owner(format($q$ update quote_lines set unit_price = 1 where id = %L $q$, tests.id('qline'))), 'ERR:42501ERR:42501');

-- 6. Accepted quote -> the project's services (snapshots) -> contract --------------------------------------------------------------------------------------
select tests.check('converting the accepted quote attaches its priced lines to the EXISTING project (a snapshot), idempotently - no second project',
  tests.scalar('web_lead', format($q$ select quote_convert_to_project(%L)::text $q$, tests.id('quote'))) || '|' || tests.scalar('web_lead', format($q$ select quote_convert_to_project(%L)::text $q$, tests.id('quote'))) || '|' || (select count(*)::text from projects where client_id = tests.id('zeta')),
  tests.id('prj')::text || '|' || tests.id('prj')::text || '|1');
select tests.check('the project now carries the service as bought: N$5,000, tied to the price version and the quote line', (select concat_ws('|', ps.unit_price::text, (ps.price_id = tests.id('price:wd1'))::text, (ps.quote_line_id = tests.id('qline'))::text, count(*) over ()::text) from project_services ps where ps.project_id = tests.id('prj')), '5000.00|true|true|1');
select tests.remember('contract', tests.scalar('web_lead', format($q$ select contract_create_from_quote(%L, 'Zeta website agreement')::text $q$, tests.id('quote'))));
select tests.check('the contract is made from the accepted quote (lines and prices copied as a snapshot), and is linked to the project', (select concat_ws('|', (c.quote_id = tests.id('quote'))::text, (select count(*)::text from contract_lines l join contract_versions v on v.id = l.version_id where v.contract_id = c.id), (select l.unit_price::text from contract_lines l join contract_versions v on v.id = l.version_id where v.contract_id = c.id limit 1), (select count(*)::text from contract_projects cp where cp.contract_id = c.id and cp.project_id = tests.id('prj'))) from contracts c where c.id = tests.id('contract')), 'true|1|5000.00|1');
select tests.check('a second contract from the same quote is refused or returns the same one (no duplicate contract)', (tests.scalar('web_lead', format($q$ select contract_create_from_quote(%L)::text $q$, tests.id('quote'))) in (tests.id('contract')::text, 'ERR:23514', 'ERR:23505', 'ERR:42501'))::text || (select count(*)::text from contracts where quote_id = tests.id('quote')), 'true1');
select tests.scalar('web_lead', format($q$ select contract_transition(%L, 'internal_review')::text $q$, tests.id('contract')));
select tests.check('the contract is approved by management (not by its preparer), then sent, signed and made active', tests.scalar('web_lead', format($q$ select contract_transition(%L, 'approved')::text $q$, tests.id('contract'))) || '|' || tests.scalar('ceo', format($q$ select contract_transition(%L, 'approved')::text $q$, tests.id('contract'))) || '|' ||
  tests.scalar('web_lead', format($q$ select contract_transition(%L, 'sent')::text $q$, tests.id('contract'))) || '|' || tests.scalar('web_lead', format($q$ select contract_transition(%L, 'signed')::text $q$, tests.id('contract'))) || '|' || tests.scalar('web_lead', format($q$ select contract_transition(%L, 'active')::text $q$, tests.id('contract'))), 'ERR:42501|approved|sent|signed|active');
select tests.scalar('web_lead', format($q$ select project_transition(%L, 'approved')::text $q$, tests.id('prj')));
select tests.check('the project moves through its lifecycle with the contract in place', tests.scalar('web_lead', format($q$ select project_transition(%L, 'active')::text $q$, tests.id('prj'))), 'active');

-- 7. Invoice and payments --------------------------------------------------------------------------------------------------------------------------------
select tests.remember('bill', tests.scalar('fin', format($q$ select billable_from_contract(%L, (select l.id from contract_lines l join contract_versions v on v.id = l.version_id where v.contract_id = %L order by v.version_no desc limit 1), 1)::text $q$, tests.id('contract'), tests.id('contract'))));
select tests.remember('inv', tests.scalar('fin', format($q$ select invoice_create(array[%L]::uuid[], %L)::text $q$, tests.id('bill'), tests.id('zed'))));
select tests.check('the invoice is created from the billable item of the contract line: amount N$5,000, the client and the contact are referenced', (select concat_ws('|', i.status::text, i.total::text, (i.client_id = tests.id('zeta'))::text, (select count(*)::text from invoice_lines l where l.invoice_id = i.id)) from invoices i where i.id = tests.id('inv')), 'draft|5000.00|true|1');
select tests.check('submit, approve (management, not the preparer), issue (finance)', tests.scalar('fin', format($q$ select invoice_transition(%L, 'pending_approval')::text $q$, tests.id('inv'))) || '|' || tests.scalar('fin', format($q$ select invoice_transition(%L, 'approved')::text $q$, tests.id('inv'))) || '|' || tests.scalar('ceo', format($q$ select invoice_transition(%L, 'approved')::text $q$, tests.id('inv'))) || '|' ||
  tests.scalar('fin', format($q$ select invoice_transition(%L, 'issued')::text $q$, tests.id('inv'))), 'pending_approval|ERR:42501|approved|issued');
select tests.check('an issued invoice carries snapshots of the client identity and the lines, and cannot be changed afterwards - not its lines, total or client, even by the owner',
  (select (client_name_snapshot is not null and client_name_snapshot = 'Zeta Test Company')::text from invoices where id = tests.id('inv')) || tests.try_owner(format($q$ update invoices set total = 1 where id = %L $q$, tests.id('inv'))) || tests.try_owner(format($q$ update invoice_lines set unit_price = 1 where invoice_id = %L $q$, tests.id('inv'))) ||
  tests.scalar('fin', format($q$ select invoice_remove_line((select id from invoice_lines where invoice_id = %L limit 1))::text $q$, tests.id('inv'))), 'trueERR:42501ERR:42501ERR:42501');
update clients set name = 'Zeta Test Company (renamed)' where id = tests.id('zeta');
select tests.check('renaming the client later does not rewrite the issued invoice', (select client_name_snapshot from invoices where id = tests.id('inv')), 'Zeta Test Company');
update clients set name = 'Zeta Test Company' where id = tests.id('zeta');
select tests.check('the outstanding balance is DERIVED from the authoritative records: N$5,000 before any payment', tests.scalar('fin', format($q$ select invoice_balance(%L)::text $q$, tests.id('inv'))), '5000.00');
select tests.remember('pay1', tests.scalar('fin', format($q$ select payment_record(%L, %L, 2000, 'bank_transfer', current_date, 'EFT-0001', %L)::text $q$, tests.id('zeta'), tests.id('acct:main'), tests.id('inv'))));
select tests.check('a partial payment of N$2,000 is recorded and allocated to the invoice; the balance is N$3,000 and the invoice is not yet paid', tests.scalar('fin', format($q$ select invoice_balance(%L)::text || '|' || invoice_paid(%L)::text $q$, tests.id('inv'), tests.id('inv'))) , '3000.00|2000.00');
select tests.check('the invoice status moves to partially paid by itself (derived), the payment has its permanent ID', (select i.status::text from invoices i where i.id = tests.id('inv')) || '|' || (select (institutional_id ~ '^[0-9A-HJKMNP-TV-Z]{9}$')::text from entity_registry where table_name = 'payments' and entity_id = tests.id('pay1')), 'partially_paid|true');
select tests.check('a payment cannot be allocated beyond its amount or beyond the invoice''s balance', tests.scalar('fin', format($q$ select payment_allocate(%L, %L, 2500)::text $q$, tests.id('pay1'), tests.id('inv'))), 'ERR:23514');
select tests.remember('pay2', tests.scalar('fin', format($q$ select payment_record(%L, %L, 3000, 'cash', current_date, 'CASH-0002', %L)::text $q$, tests.id('zeta'), tests.id('acct:main'), tests.id('inv'))));
select tests.check('the client 360 shows the finance position, derived from invoices and allocations (invoiced 5000, paid 5000, outstanding 0), and both payments', tests.scalar('fin', format($q$ select (client_360(%L) -> 'finance_summary' ->> 'invoiced') || '|' || (client_360(%L) -> 'finance_summary' ->> 'outstanding') || '|' || jsonb_array_length(client_360(%L) -> 'payments')::text $q$, tests.id('zeta'), tests.id('zeta'), tests.id('zeta'))), '5000.00|0|2');
select tests.check('there is no stored balance anywhere: invoices and payments carry no balance, outstanding or paid-amount column', (select coalesce(string_agg(table_name || '.' || column_name, ','), 'none') from information_schema.columns where table_name in ('invoices', 'payments', 'clients', 'projects') and column_name ~* 'balance|outstanding|amount_paid|paid_amount'), 'none');

-- 8. Documents ---------------------------------------------------------------------------------------------------------------------------------------------
select tests.check('a project document is registered once and attached to the project by relationship (no project-specific storage)', (tests.mk_doc('web_lead', 'zdoc', 'Zeta website brief', 'requirements', 'web', 'prj') ~ '^[0-9a-f-]{36}$')::text, 'true');
select tests.check('...and to the client as well (one record, two relationships)', tests.scalar('web_lead', format($q$ select (document_link_add(%L, (select institutional_id from entity_registry where entity_id = %L))::text ~ '^[0-9a-f-]{36}$')::text $q$, tests.id('doc:zdoc'), tests.id('zeta'))), 'true');
select tests.add_ver('web_lead', 'zdoc', 'zv1', 'the brief for the zeta site');
select tests.check('the lead opens it through document_open (which logs the read)', tests.scalar('web_lead', format($q$ select (document_open(%L, 'read') ->> 'version_no') $q$, tests.id('doc:zdoc'))), '1');
select tests.check('the client 360 and the project 360 list the document (one record, two relationships), classification internal', tests.scalar('web_lead', format($q$ select jsonb_array_length(client_360(%L) -> 'documents')::text || jsonb_array_length(project_360(%L) -> 'documents')::text $q$, tests.id('zeta'), tests.id('prj'))), '11');
select tests.try('ceo', format($q$ select document_hold_place(%L, 'dispute') $q$, tests.id('doc:zdoc')));
select tests.check('retention and legal hold apply to it unchanged: a hold is placed through the document module and shows in its retention position', (select on_legal_hold::text from document_retention_status where document_id = tests.id('doc:zdoc')), 'true');
-- 9. Communications -----------------------------------------------------------------------------------------------------------------------------------------
select tests.mk_thread('web_lead', 'zc', 'Kick-off call with Zed');
select tests.say('web_lead', 'zc', 'zc1', 'phone_call', 'outbound', 'Agreed scope and timeline', jsonb_build_array(jsonb_build_object('role', 'callee', 'entity', (select institutional_id from entity_registry where entity_id = tests.id('zed')))));
select tests.clink('web_lead', 'zc', 'clients', 'zeta');
select tests.clink('web_lead', 'zc', 'projects', 'prj', 'related');
select tests.check('a communication is recorded against the client and the project; the Client and Project 360 show its METADATA, not its subject or content', tests.scalar('web_lead', format($q$ select jsonb_array_length(client_360(%L) -> 'communications')::text || jsonb_array_length(project_360(%L) -> 'communications')::text || ((client_360(%L)::text ~* 'Kick-off|Agreed scope')::text) $q$, tests.id('zeta'), tests.id('prj'), tests.id('zeta'))), '11false');
select tests.check('the content stays behind the read right: the sales lead reads it, finance (view only) does not and is told nothing', tests.scalar('web_lead', format($q$ select (communication_read(%L) -> 'messages' -> 0 ->> 'body') $q$, tests.id('thr:zc'))) || '|' || tests.scalar('fin', format($q$ select coalesce(communication_read(%L)::text, 'null') $q$, tests.id('thr:zc'))) || '|' || tests.scalar('fin', format($q$ select jsonb_array_length(client_360(%L) -> 'communications')::text $q$, tests.id('zeta'))), 'Agreed scope and timeline|null|1');

-- 10. Assets and tickets -----------------------------------------------------------------------------------------------------------------------------------------
select tests.remember('asset', tests.scalar('web_lead', format($q$ select asset_create('Zeta office router', 'network', %L, p_manufacturer => 'Mikrotik', p_model => 'hAP ax3', p_serial => 'SN-ZETA-001', p_tag => 'ZT-RTR-1', p_client => %L, p_project => %L)::text $q$, tests.id('div:web'), tests.id('zeta'), tests.id('prj'))));
create temp table asset_id as select institutional_id from entity_registry where table_name = 'assets' and entity_id = tests.id('asset');
select tests.check('the asset is one authoritative record with its own permanent ID, referencing the client and the project', (select concat_ws('|', (a.client_id = tests.id('zeta'))::text, (a.project_id = tests.id('prj'))::text, ((select institutional_id from asset_id) ~ '^[0-9A-HJKMNP-TV-Z]{9}$')::text) from assets a where a.id = tests.id('asset')), 'true|true|true');
select tests.try('web_lead', format($q$ select asset_transition(%L, 'acquired') $q$, tests.id('asset')));
select tests.try('web_lead', format($q$ select asset_transition(%L, 'in_stock') $q$, tests.id('asset')));
select tests.check('assigning it to staff and moving it between divisions and locations keeps its permanent identity', tests.try('web_lead', format($q$ select asset_assign(%L, %L, %L, 'installed at the client', %L) $q$, tests.id('asset'), tests.id('staff:web_staff'), tests.id('div:web'), tests.id('prj'))) ||
  (select (institutional_id = (select institutional_id from asset_id))::text from entity_registry where table_name = 'assets' and entity_id = tests.id('asset')), 'oktrue');
select tests.remember('ticket', tests.scalar('web_staff', format($q$ select ticket_create('Zeta site is slow', 'The home page takes long to load', %L, %L, %L, %L, %L)::text $q$, tests.id('asset'), tests.id('div:web'), tests.id('zeta'), tests.id('prj'), tests.id('zed'))));
select tests.check('a ticket references the client, the project, the contact and the asset (nothing copied), and gets its own permanent ID', (select concat_ws('|', (t.client_id = tests.id('zeta'))::text, (t.project_id = tests.id('prj'))::text, (t.asset_id = tests.id('asset'))::text, (t.contact_id = tests.id('zed'))::text, (t.ada_id ~ '^ADA-TKT-')::text) from tickets t where t.id = tests.id('ticket')), 'true|true|true|true|true');
select tests.check('the client 360 reaches the ticket and the asset; the project 360 reaches both too; the asset 360 reaches the project and the ticket', tests.scalar('web_lead', format($q$ select jsonb_array_length(client_360(%L) -> 'tickets')::text || jsonb_array_length(client_360(%L) -> 'assets')::text || jsonb_array_length(project_360(%L) -> 'tickets')::text || jsonb_array_length(project_360(%L) -> 'assets')::text || (asset_360(%L)::text ~ 'Zeta Website')::text $q$, tests.id('zeta'), tests.id('zeta'), tests.id('prj'), tests.id('prj'), tests.id('asset'))), '1111true');
-- 11. Domain -------------------------------------------------------------------------------------------------------------------------------------------------------------
select tests.remember_ok('dom:zdom', tests.scalar('web_lead', format($q$ select (domain_create('zeta-test.example', %L) ->> 'id') $q$, tests.id('div:web'))));
select tests.rel('web_lead', 'zdom', 'client', 'clients', 'zeta');
select tests.check('the domain is related to the client by reference and shows in the client 360', tests.scalar('web_lead', format($q$ select jsonb_array_length(client_360(%L) -> 'domains')::text $q$, tests.id('zeta'))), '1');

-- 12. Client 360 and Project 360: controlled views over the authoritative relationships ---------------------------------------------------------------------
select tests.check('Client 360 carries the organization, the relationship, the contact, the project, the quote, the contract, the invoice, both payments, the document, the communication metadata, the domain, the ticket and the asset - each as a reference to its own record',
  tests.scalar('web_lead', format($q$ select (select string_agg(k || ':' || jsonb_array_length(client_360(%L) -> k)::text, ',' order by k) from unnest(array['assets','communications','contacts','contracts','documents','domains','invoices','projects','quotes','tickets']) k) $q$, tests.id('zeta'))),
  'assets:1,communications:1,contacts:1,contracts:1,documents:1,domains:1,invoices:1,projects:1,quotes:1,tickets:1');
select tests.check('...and finance, who alone sees payments, sees both in the same 360', tests.scalar('fin', format($q$ select jsonb_array_length(client_360(%L) -> 'payments')::text $q$, tests.id('zeta'))), '2');
select tests.check('Project 360 carries the client, the contact, the participating divisions, the staff, the service as bought, the quote, the contract, the invoice, the document, the communication, the ticket, the asset and the task',
  tests.scalar('web_lead', format($q$ select (select string_agg(k || ':' || jsonb_array_length(project_360(%L) -> k)::text, ',' order by k) from unnest(array['assets','communications','contacts','contracts','divisions','documents','invoices','quotes','services','staff','tickets']) k) $q$, tests.id('prj'))),
  'assets:1,communications:1,contacts:1,contracts:1,divisions:2,documents:1,invoices:1,quotes:1,services:1,staff:2,tickets:1');
select tests.check('...and the task, from the task list (open 1)', tests.scalar('web_lead', format($q$ select (project_360(%L) -> 'tasks' ->> 'open') || jsonb_array_length(project_360(%L) -> 'tasks' -> 'items')::text $q$, tests.id('prj'), tests.id('prj'))), '11');
select tests.check('...and the client of the project is the one Zeta record', tests.scalar('web_lead', format($q$ select (project_360(%L) -> 'client' ->> 'name') $q$, tests.id('prj'))), 'Zeta Test Company');
select tests.check('the 360 views are views, not tables: no client, project or organization table has a column for invoices, payments, documents, communications, tickets or assets', (select coalesce(string_agg(table_name || '.' || column_name, ','), 'none') from information_schema.columns where table_name in ('clients', 'projects', 'organizations') and column_name ~* 'invoice|payment|document|communication|ticket|asset_|domain_'), 'none');

-- 13. Search is the way in --------------------------------------------------------------------------------------------------------------------------------
select tests.check('typing "Zeta" finds the people and records of the engagement - the organization, the client, the contact, the project, the quote, the contract, the invoice, the payments, the document, the domain, the ticket and the asset',
  tests.scalar('web_lead', $q$ select (select string_agg(distinct x ->> 'entity_type', ',' order by x ->> 'entity_type') from jsonb_array_elements(search('zeta')->'results') x) $q$), 'asset,client,contract,document,domain,external_organization,invoice,person,project,quote,ticket');
select tests.check('"type:client Zeta" reaches exactly the client, and the client''s institutional and legacy IDs resolve to it', tests.scalar('web_lead', format($q$ select (search('type:client zeta')->>'total') || '|' || (search(%L)->'results'->0->>'label') || '|' || (search(lower(%L))->'results'->0->>'entity_type') $q$, (select client_inst from zeta), (select client_ada from zeta))), '1|Zeta Test Company|client');
select tests.check('finance reaches the invoice and the payments by number and by reference', tests.scalar('fin', format($q$ select (search('type:invoice %s')->>'total') || (search('EFT-0001')->>'total') || (search('type:payment cash')->>'total') $q$, (select ada_id from invoices where id = tests.id('inv')))), '111');
select tests.check('"related:<client ID>" reaches everything connected to the client that the caller may see (project, quote, contract, invoice, document, domain, communication, ticket, asset)',
  tests.scalar('web_lead', format($q$ select (select string_agg(distinct x ->> 'entity_type', ',' order by x ->> 'entity_type') from jsonb_array_elements(search('related:%s')->'results') x) $q$, (select client_inst from zeta))), 'asset,communication,contract,document,domain,invoice,project,quote,ticket');

-- 14. History, audit, stable identities --------------------------------------------------------------------------------------------------------------------
select tests.check('every step of the engagement is in the audit trail, attributed to a person: the organization, client, contact, project, quote and its lines, contract, invoice, payments and allocations, document, communication, ticket, asset and domain',
  (select string_agg(table_name, ',' order by table_name) from (select distinct table_name from audit_log where actor_staff_id is not null and table_name in ('clients', 'organizations', 'client_contacts', 'people', 'projects', 'quotes', 'quote_lines', 'contracts', 'invoices', 'payments', 'payment_allocations', 'documents', 'communication_threads', 'tickets', 'assets', 'domains', 'approval_requests', 'approval_decisions')) q),
  'assets,client_contacts,clients,communication_threads,contracts,documents,domains,invoices,organizations,payment_allocations,payments,people,projects,quote_lines,quotes,tickets');
select tests.check('the CEO''s Client 360 carries the recent history of the client from the audit trail; the sales lead (without audit rights) is not shown it', tests.scalar('ceo', format($q$ select (jsonb_array_length(client_360(%L) -> 'activity') > 0)::text $q$, tests.id('zeta'))) || tests.scalar('web_lead', format($q$ select jsonb_array_length(client_360(%L) -> 'activity')::text $q$, tests.id('zeta'))), 'true0');
select tests.check('approvals are recorded with their decisions: the quote, the invoice and both prices were each decided by a person other than the preparer', (select string_agg(r.entity_table, ',' order by r.entity_table) from approval_requests r where r.status = 'approved' and r.entity_table in ('quotes', 'contracts', 'invoices', 'service_prices')
   and not exists (select 1 from approval_decisions d where d.request_id = r.id and d.is_self)), 'invoices,quotes,service_prices,service_prices');
select tests.check('the institutional IDs of the engagement never changed during it: client, project, quote, contract, invoice, payments, document, thread, asset, ticket, domain all still have one registry row each',
  (select count(*)::text from (select 1 from entity_registry where entity_id in (tests.id('zeta'), tests.id('prj'), tests.id('quote'), tests.id('contract'), tests.id('inv'), tests.id('pay1'), tests.id('pay2'), tests.id('doc:zdoc'), tests.id('thr:zc'), tests.id('asset'), tests.id('ticket'), tests.id('dom:zdom')) group by entity_id having count(*) = 1) q), '12');
select tests.check('no engagement record exists twice: one organization, one client, one contact, one person, one project, one quote, one contract, one invoice', (select (select count(*) from organizations where lower(name) = 'zeta test company')::text || (select count(*) from clients where lower(name) = 'zeta test company') || (select count(*) from client_contacts where client_id = tests.id('zeta')) || (select count(*) from people where lower(email) = 'zed@zeta.example') ||
  (select count(*) from projects where client_id = tests.id('zeta')) || (select count(*) from quotes where client_id = tests.id('zeta')) || (select count(*) from contracts where client_id = tests.id('zeta')) || (select count(*) from invoices where client_id = tests.id('zeta'))), '11111111');
-- pilot_record: the authoritative rows behind the ids a screen shows ---------------------------------------------------------------------------------------------
select tests.check('pilot_record shows the quote with its price snapshot lines and its approval history, and the invoice with its derived balance and allocations',
  concat_ws('|', tests.scalar('web_lead', format($q$ select (pilot_record(%L) -> 'record' ->> 'status') || ':' || (pilot_record(%L) -> 'record' -> 'lines' -> 0 ->> 'unit_price') || ':' || jsonb_array_length(pilot_record(%L) -> 'record' -> 'approvals') $q$,
      (select institutional_id from entity_registry where entity_id = tests.id('quote')), (select institutional_id from entity_registry where entity_id = tests.id('quote')), (select institutional_id from entity_registry where entity_id = tests.id('quote')))),
    tests.scalar('fin', format($q$ select (pilot_record(%L) -> 'record' ->> 'balance') || ':' || jsonb_array_length(pilot_record(%L) -> 'record' -> 'allocations') $q$,
      (select institutional_id from entity_registry where entity_id = tests.id('inv')), (select institutional_id from entity_registry where entity_id = tests.id('inv'))))), 'accepted:5000.00:1|0.00:2');
select tests.check('pilot_record answers null for a missing id and for a payment the caller may not read', tests.scalar('web_lead', $q$ select coalesce(pilot_record('ZZZZZZZZZ')::text, 'null') $q$) || '|' || tests.scalar('web_lead', format($q$ select coalesce(pilot_record(%L)::text, 'null') $q$, (select institutional_id from entity_registry where table_name = 'payments' limit 1))), 'null|null');
-- domain_relation_add: the Domains module's own relation insert, as an operation
select tests.remember_ok('dom:zdom2', tests.scalar('web_lead', format($q$ select (domain_create('zeta-shop.example', %L) ->> 'id') $q$, tests.id('div:web'))));
select tests.check('a domain is related to the project through the operation; it then shows in Project 360 and in search related:, once only (a repeat is refused, not duplicated)',
  concat_ws('|', tests.try('web_lead', format($q$ select domain_relation_add(%L, 'project', %L, 'shop site')::text $q$, tests.id('dom:zdom2'), (select institutional_id from entity_registry where entity_id = tests.id('prj')))),
    tests.try('web_lead', format($q$ select domain_relation_add(%L, 'project', %L, 'again')::text $q$, tests.id('dom:zdom2'), (select institutional_id from entity_registry where entity_id = tests.id('prj')))),
    tests.scalar('web_lead', format($q$ select jsonb_array_length(project_360(%L) -> 'domains')::text $q$, tests.id('prj'))),
    tests.try('tech_lead', format($q$ select domain_relation_add(%L, 'client', %L)::text $q$, tests.id('dom:zdom2'), (select institutional_id from entity_registry where entity_id = tests.id('zeta'))))),
  'ok|ERR:23505|1|ERR:42501');
select tests.finish();
rollback;
